    [2283] = {n="Necklace Recovery", d="Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged.", tgo={{"Shadowforge Surveyor", "Shadowforge Ruffian", "Shadowforge Digger"}}},
    [2284] = {n="Necklace Recovery, Take 2", d="Find a clue as to the gems' whereabouts in the depths of Uldaman."},
    [2318] = {n="Translating the Journal", d="Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands."},
    [2338] = {n="Translating the Journal", d="Let Jarkal borrow the necklace. In exchange, he will translate the journal for you."},
    [2339] = {n="Find the Gems and Power Source", d="Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.", tgo={{}, {"Grimlok"}, {}, {"Archaedas"}}, objs={"Shadowforge Cache", "Conspicuous Urn"}},
    [2340] = {n="Deliver the Gems", d="Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar."},
    [2341] = {n="Necklace Recovery, Take 3", d="Visit Jarkal Mossmeld in Kargath to see if he was successful."},
    [2342] = {n="Reclaimed Treasures", d="Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.", objs={"Garrett Family Chest"}},
    [2378] = {n="Find the Shattered Hand", d="Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow."},
    [2379] = {n="Zando'zan", d="Speak with Zando'zan at the Cleft of Shadow."},
    [2381] = {n="Plundering the Plunderers", d="Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!", tgo={{"Polly"}}},
    [2382] = {n="Wrenix of Ratchet", d="Travel to Ratchet and speak with Wrenix the Wretched."},
    [2383] = {n="Simple Parchment", d="Read the Simple Parchment and speak to Frang in the Valley of Trials."},
    [2418] = {n="Power Stones", d="Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.", tgo={{"Shadowforge Surveyor", "Shadowforge Ruffian", "Shadowforge Digger"}, {"Shadowforge Surveyor", "Shadowforge Ruffian", "Shadowforge Digger"}}},
    [2458] = {n="Deep Cover", d="Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize."},
    [2460] = {n="The Shattered Salute", d="Perform the Shattered Salute on Shenthul.", tgo={{"Shenthul"}}},
    [2478] = {n="Mission: Possible But Not Probable", d="Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.", tgo={{"Mutated Venture Co. Drone"}, {"Venture Co. Lookout"}, {"Venture Co. Patroller"}, {"Grand Foreman Puzik Gallywix"}, {"Foreman Silixiz"}, {}}, objs={"Gallywix's Lockbox"}},
    [2479] = {n="Hinott's Assistance", d="Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!"},
    [2480] = {n="Hinott's Assistance", d="Wait for Serge Hinott to complete the cure."},
    [2521] = {n="To Serve Kum'isha", d="In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.", tgo={{"Dreadmaul Ogre", "Dreadmaul Ogre Mage", "Dreadmaul Brute"}}},
    [2581] = {n="Snickerfang Jowls", d="Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", tgo={{"Starving Snickerfang", "Snickerfang Hyena", "Ravage"}, {"Ashmane Boar", "Helboar", "Grunter"}, {"Scorpok Stinger", "Clack the Reaver"}}},
