    [97485] = {n="Traditions of the Bluff", d="Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Cedar Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\nCombine the items and sprinkle the incense off of Hunter's Rise.", objs={"Incense Burner"}},
    [97530] = {n="Dunemaul Dues", d="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to recover a particularly shiny bangle bracelet lost near the Dunemaul ogre compound.", tgo={{"Dunemaul Ogre", "Dunemaul Enforcer", "Dunemaul Ogre Mage"}}},
    [97534] = {n="Gritty Business", d="Quinn wants you to recover 7 pieces of Desert Debris and return to her in Gadgetzan."},
    [97539] = {n="Silky Sutures", d="Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands.", tgo={{"Plains Creeper", "Giant Plains Creeper"}}},
    [97558] = {n="Hides for the Forsaken", d="Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin.", tgo={{"Greater Duskbat", "Vampiric Duskbat"}, {"Decrepit Darkhound", "Cursed Darkhound"}, {"Vile Fin Minor Oracle", "Vile Fin Muckdweller"}}},
    [97908] = {n="Camping 101: Skinning", d="Speak with Thuwd in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", tgo={{"Thuwd"}}},
    [97936] = {n="Camping 101: Skinning", d="Speak with Yonn Deepcut in Bloodhoof Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", tgo={{"Yonn Deepcut"}}},
    [98024] = {n="Journey to the Crossroads", d="Report To Thork at The Crossroads in The Barrens."},
    [98069] = {n="Stolen Freewind Supplies", d="Bring 8 Stolen Freewind Supplies to Jandia in Freewind Post."},
    [98070] = {n="Stop the Screeching", d="Slay 5 Screeching Harpies, 5 Screeching Roguefeather Harpies and 5 Screeching Windcaller Harpies.", tgo={{"Screeching Harpy"}, {"Screeching Roguefeather"}, {"Screeching Windcaller"}}},
    [98093] = {n="Field to Clear", d="Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely.", tgo={{"Hecklefang Stalker"}, {"Stormhide"}}},
    [98094] = {n="Scout Support", d="High Executor Darthalia wants you to deliver updated orders to Deathstalker Masoj, south of Tarren Mill, outside of Dun Garok."},
    [98095] = {n="Valuable Vantages", d="Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him."},
    [98298] = {n="Arugal's Folly", d="Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher.", tgo={{"Moonrage Bloodhowler"}}},
    [98299] = {n="Stop the Spread", d="Slay 5 Sickly Refugees and 5 Haggard Refugees for Dalar Dawnweaver in The Sepulcher.", tgo={{"Haggard Refugee"}, {"Sickly Refugee"}}},
    [98340] = {n="The Great Cat Spirit", d="Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."},
    [98341] = {n="The Great Windborne Cat Spirit", d="Seek out the Avatar of Saeyleenan in the southern part Moonglade and learn what it has to share with you about the nature of the windborne cat."},
    [98342] = {n="The Great Cat Spirit", d="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit.", objs={"Relic of the Fang", "Relic of the Claw", "Relic of the Silent Shadow"}},
    [98362] = {n="To Thunder Bluff", d="Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise."},
    [98389] = {n="A Light in the Darkness", d="Free 6 Webbed Victims in Night's Web Hollow for Aramis Hammerhand in Deathknell."},
    [98404] = {n="The Great Windborne Cat Spirit", d="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Avatar of Saeyleenan.", objs={"Relic of the Fang", "Relic of the Claw", "Relic of the Silent Shadow"}},
    [98405] = {n="The Great Cat Spirit", d="Seek out the Great Cat Spirit in southern part Moonglade and learn what it has to share with you about the nature of the cat."},
    [98424] = {n="Fizsprocket's Notes", d="Collect the rest of Supervisor Fizsprocket's pages inside The Venture Co. Mine and bring them to Morin Cloudstalker near Bloodhoof Village.", objs={"Shredder Operation Instructions", "Barrens Operations Best Practices", "One \"Gerenzo\", of Stonetalon"}},
    [98427] = {n="Ceasing Operations", d="Bring the Clearcutter Key to Morin Cloudstalker outside Bloodhoof Village.", tgo={{"Venture Co. Clearclutter"}}},
    [98430] = {n="The Longwalkers", d="Help Perith Stormhoof escape Palemane Rock, and report his safety to Cairne Bloodhoof in Thunder Bluff."},
    [98435] = {n="Thunderhorn's Report", d="Bring Thunderhorn's Report to Arch Druid Hamuul Runetotem in Thunder Bluff."},
    [98575] = {n="Tainted Tablet", d="Read the Tainted Tablet and speak to Nartok inside the Den in the Valley of Trials."},
    [98576] = {n="Glyphic Parchment", d="Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials."},
    [98601] = {n="A Difficult Path", d="Read the Consecrated Scroll and speak to Aramis Hammerhand in the church in Deathknell."},
    [98738] = {n="Blessings of the Great Windborne Cat Spirit", d="Speak to Dendrite."},
    [98739] = {n="Blessings of the Great Cat Spirit", d="Speak to Dendrite."},
    [98823] = {n="Earthen Echo", d="Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore."},
    [99048] = {n="A Missing Hand", d="Find Heglan Shadeeye north of Tiragarde Keep."},
    [99049] = {n="Threat from Below", d="Find signs of what attacked Heglan Shadeeye.", objs={"Abandoned Dagger", "Strange Debris", "Weapon Piece"}},
    [99051] = {n="Threat from Below", d="Collect 9 Naga Spinefins.", tgo={{"Spitelash Scout", "Spitelash Attendant"}}},
    [99052] = {n="Threat from Below", d="Kill the sea giant along Durotar's north coast and bring back proof of your accomplishment.", tgo={{"Aggor the Young"}}},
    [99079] = {n="Longwalker Malah", d="Find Longwalker Malah Longwind east of Bloodhoof Village, near the edge of Mulgore."},
    [99080] = {n="Drive Them Out", d="Kill 6 Galak Centaurs, 4 Galak Outrunners, and bring the head of Herak the Pillager to Baine Bloodhoof.", tgo={{"Galak Centaur"}, {"Galak Outrunner"}, {"Herak the Pillager"}}},
    [99081] = {n="Grim Tidings", d="Bring Longwalker Malah's Report to Brave Wildrunner in Bloodhoof Village."},
    [99082] = {n="The High Chieftain", d="Seek audience with High Chieftain Cairne Bloodhoof in Thunder Bluff."},
    [99101] = {n="Our Ancient Enemy", d="Bring Longwalker Malah's Report to Baine Bloodhoof."},
    [99108] = {n="Sparring Match", d="Defeat 3 other players in duels or Novice Warriors for Tang Stonehoof.", tgo={{"Novice Warrior"}}},
    [99123] = {n="Lost in the Shadows", d="Help Pal'juh escape Kolkar Crag and bring news of your success to Master Vornal in Sen'jin Village."},
    [99134] = {n="Discipline", d="Punish 5 Deathguards for Executor Zygand."},
    [99141] = {n="Patience", d="Obtain reports from Deathguard Dillinger, Deathguard Kristof, and Gordo for Executor Zygand.", tgo={{"Deathguard Dillinger"}, {"Deathguard Kristof"}, {"Gordo"}}},
    [99142] = {n="Tomb Weed", d="Collect 5 Tomb Weed and deliver them back to Junior Apothecary Holland.", objs={"Tomb Weed"}},
    [99156] = {n="Rear Guard Patrol", d="Bring Riptear's Heart to Deathguard Linnea.", tgo={{"Riptear"}}},
    [99187] = {n="The Reliquary of Tyr", d="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", star={"Sword of Mourning", {"PALADIN"}}},
    [99411] = {n="Kyle's Gone Missing!", d="Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\nFeed Kyle Tender Strider Meat and return to Ahab Wheathoof.", tgo={{"Kyle the Frenzied"}}},
